```ts
import type {} from "cordis";

export type ExpiryStatus = "healthy" | "expiring" | "expired" | "missing";

export interface ExpiryBatch {
  readonly id: string;
  readonly itemId: string;
  readonly batchNo: string;
  readonly quantity: number;
  readonly expiresAt: string; // ISO date (YYYY-MM-DD)
  readonly note?: string;
  readonly createdAt: string;
  readonly updatedAt: string;
}

export interface ExpiryBatchView extends ExpiryBatch {
  readonly sku: string;
  readonly itemName: string;
  readonly unit: string;
  readonly daysRemaining: number;
  readonly status: ExpiryStatus;
  readonly isExpiringSoon: boolean;
  readonly isExpired: boolean;
}

export interface CreateExpiryBatchInput {
  readonly itemId: string;
  readonly batchNo: string;
  readonly quantity: number;
  readonly expiresAt: string;
  readonly note?: string;
}

export interface ExpiryAlertSummary {
  readonly totalBatches: number;
  readonly expiringCount: number;
  readonly expiredCount: number;
  readonly nearExpiryItemIds: readonly string[];
  readonly batches: readonly ExpiryBatchView[];
  readonly thresholdDays: number;
}

export interface InventoryExpiryService {
  listBatches(itemId?: string): ExpiryBatchView[];
  getBatch(id: string): ExpiryBatchView | null;
  registerBatch(input: CreateExpiryBatchInput): Promise<ExpiryBatchView>;
  removeBatch(id: string): boolean;
  listAlerts(thresholdDays?: number): ExpiryAlertSummary;
}

declare module "cordis" {
  interface Context {
    inventoryExpiry: InventoryExpiryService;
  }
  interface Events {
    "inventory-expiry:batch-registered"(payload: { batch: ExpiryBatchView; item: InventoryItem }): void;
    "inventory-expiry:alert-raised"(payload: { batch: ExpiryBatchView; thresholdDays: number }): void;
  }
}

export interface InventoryExpiryBadgeSlotContext {
  readonly item: InventoryItemRef...;
}
```

