import { Service, type Context } from "cordis";
import type { ScopedDb } from "@host/server-sdk";
import type {
  CreateExpiryBatchInput,
  ExpiryAlerts,
  ExpiryBatch,
  ExpiryBatchStatus,
  ExpiryBatchView,
  ExpiryInventoryItem,
  InventoryExpiryService,
} from "./contract.d.ts";

const DEFAULT_THRESHOLD_DAYS = 30;
const MAX_THRESHOLD_DAYS = 3650;

interface BatchRow { id: string; item_id: string; batch_no: string; quantity: number; expires_at: string; note: string | null; created_at: string; updated_at: string; }

function httpError(status, message) {...}

function isoDay(offsetDays = 0, now = new Date()): string {
  const utc = Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate()) + offsetDays * 86400000;
  return new Date(utc).toISOString().slice(0, 10);
}

function parseDateOnly(value: unknown): string | null {...}

function daysRemaining(expiresAt: string, now = new Date()): number {
  const expiry = Date.parse(`${expiresAt}T00:00:00.000Z`);
  const today = Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate());
  return Math.round((expiry - today) / 86400000);
}

function normalizeThreshold(value?: number): number {
  if (typeof value !== "number" || !Number.isFinite(value)) return DEFAULT_THRESHOLD_DAYS;
  return Math.min(MAX_THRESHOLD_DAYS, Math.max(0, Math.trunc(value)));
}

function readQuery(req: unknown, key: string): string | undefined {...}

function readNumberQuery(req, key): number | undefined { const raw = readQuery; if (!raw) return undefined; const n = Number(raw); return Number.isFinite(n) ? n : undefined; }
