    setBusy(true);
    setFormError("");
    try {
      await requestJson(`${EXPIRY_API}/batches`, {
        method: "POST",
        body: JSON.stringify({
          itemId,
          batchNo: batchNo.trim(),
          quantity: Math.trunc(parsedQuantity),
          expiresAt,
        }),
      });
      setBatchNo("");
      setQuantity("1");
      setExpiresAt("");
      notifyExpiryChanged();
    } catch (err) {
      setFormError(errorMessage(err));
    } finally {
      setBusy(false);
    }
  };

  const handleDelete = async (batch: ExpiryBatchView) => {
    if (busy) return;
    setBusy(true);
    setFormError("");
    try {
      await requestJson(
        `${EXPIRY_API}/batches/${encodeURIComponent(batch.id)}`,
        { method: "DELETE" },
      );
      notifyExpiryChanged();
    } catch (err) {
      setFormError(errorMessage(err));
    } finally {
