                  <span className="text-sm font-medium">{batch.itemName}</span>
                  <span className="font-mono text-xs text-muted">
                    批次 {batch.batchNo}
                  </span>
                  <span
                    className={`rounded px-2 py-0.5 text-[11px] font-medium ${expiryBadgeClass(batch.status)}`}
                  >
                    {expiryStatusLabel(batch.status)}
                  </span>
                </div>
                <div className="flex flex-wrap items-center gap-2 text-xs text-muted">
                  <span>
                    {batch.quantity} {batch.unit}
                  </span>
                  <span>{batch.expiresAt}</span>
                  <span
                    className={
                      batch.status === "expired" ? "font-medium text-danger" : ""
                    }
                  >
                    {expiryStatusText(batch)}
                  </span>
                  <button
                    type="button"
                    data-expiry-page-delete={batch.batchNo}
                    disabled={busy}
                    onClick={() => void handleDelete(batch)}
                    className="rounded border border-line bg-canvas px-2 py-0.5 text-[11px] text-muted hover:bg-line/40 disabled:opacity-50"
                  >
                    删除
                  </button>
                </div>
              </div>
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}

type SlotRegistrar = (name: string, component: unknown) => void;

interface SlotRegistryLike {
  register?: (name: string, component: unknown) => void;
}

/**
 * Register a component into a host slot. The concrete registry lives on the
 * client context; probe the known shapes so the plugin stays compatible with
 * the host client SDK while keeping registration declarative.
 */
function registerClientSlot(
  ctx: Context,
  name: string,
  component: unknown,
): void {
  const runtime = ctx as unknown as {
    slot?: SlotRegistryLike | SlotRegistrar;
    slots?: SlotRegistryLike;
    slotRegistry?: SlotRegistryLike;
    registerSlot?: SlotRegistrar;
    client?: { slot?: SlotRegistryLike; slots?: SlotRegistryLike };
    router?: SlotRegistryLike & {
      registerSlot?: SlotRegistrar;
      slot?: SlotRegistryLike;
      slots?: SlotRegistryLike;
    };
  };

  const candidates: SlotRegistrar[] = [];
  if (
    runtime.slot &&
    typeof runtime.slot === "object" &&
