      name: "效期测试商品",
      quantity: 20,
      unit: "盒",
    },
  });
  assert.equal(created.status, 201);
  const item = (created.body as ItemPayload).item;

  const nearNo = `NEAR-${suffix}`;
  const near = await ctx.request({
    method: "POST",
    path: "/api/app/inventory-expiry/batches",
    body: {
      itemId: item.id,
      batchNo: nearNo,
      quantity: 5,
      expiresAt: utcDay(10),
      note: "临期批次",
    },
  });
  assert.equal(near.status, 201);
  const nearBatch = (near.body as BatchPayload).batch;
  assert.equal(nearBatch.itemId, item.id);
  assert.equal(nearBatch.status, "expiring");
  assert.equal(nearBatch.daysRemaining, 10);
  assert.equal(nearBatch.isExpiringSoon, true);
  assert.equal(nearBatch.isExpired, false);

  const expiredNo = `PAST-${suffix}`;
  const expired = await ctx.request({
    method: "POST",
    path: "/api/app/inventory-expiry/batches",
    body: {
      itemId: item.id,
      batchNo: expiredNo,
      quantity: 2,
      expiresAt: utcDay(-3),
    },
  });
  assert.equal(expired.status, 201);
  const expiredBatch = (expired.body as BatchPayload).batch;
  assert.equal(expiredBatch.status, "expired");
  assert.equal(expiredBatch.daysRemaining, -3);
  assert.equal(expiredBatch.isExpired, true);
  assert.equal(expiredBatch.isExpiringSoon, false);

  const freshNo = `FRESH-${suffix}`;
  const fresh = await ctx.request({
    method: "POST",
    path: "/api/app/inventory-expiry/batches",
    body: {
      itemId: item.id,
      batchNo: freshNo,
      quantity: 8,
      expiresAt: utcDay(120),
    },
  });
  assert.equal(fresh.status, 201);
  const freshBatch = (fresh.body as BatchPayload).batch;
  assert.equal(freshBatch.status, "healthy");
  assert.equal(freshBatch.isExpiringSoon, false);
  assert.equal(freshBatch.isExpired, false);

  const single = await ctx.request({
    method: "GET",
    path: `/api/app/inventory-expiry/batches/${nearBatch.id}`,
  });
  assert.equal(single.status, 200);
  assert.equal((single.body as BatchPayload).batch.batchNo, nearNo);

  const itemBatches = await ctx.request({
    method: "GET",
    path: `/api/app/inventory-expiry/items/${item.id}/batches?days=30`,
  });
  assert.equal(itemBatches.status, 200);
  const listed = (itemBatches.body as BatchListPayload).batches;
  assert.deepEqual(
    listed.map((batch) => batch.batchNo),
    [expiredNo, nearNo, freshNo],
  );
  assert.deepEqual(
    listed.map((batch) => batch.status),
    ["expired", "expiring", "healthy"],
  );

  const alerts = await ctx.request({
    method: "GET",
    path: "/api/app/inventory-expiry/alerts?days=30",
  });
  assert.equal(alerts.status, 200);
  const alertBody = alerts.body as AlertPayload;
  assert.equal(alertBody.thresholdDays, 30);
  assert.ok(alertBody.totalBatches >= 3);
  assert.ok(alertBody.expiringCount >= 1);
  assert.ok(alertBody.expiredCount >= 1);
  assert.ok(alertBody.affectedItemIds.includes(item.id));
  assert.deepEqual(
    alertBody.batches
      .filter((batch) => batch.itemId === item.id)
      .map((batch) => batch.batchNo),
    [expiredNo, nearNo],
  );

  const tight = await ctx.request({
    method: "GET",
    path: "/api/app/inventory-expiry/alerts?days=7",
  });
  assert.equal(tight.status, 200);
  const tightBody = tight.body as AlertPayload;
  assert.equal(tightBody.thresholdDays, 7);
  assert.deepEqual(
    tightBody.batches
      .filter((batch) => batch.itemId === item.id)
      .map((batch) => batch.batchNo),
    [expiredNo],
  );

  const duplicate = await ctx.request({
    method: "POST",
    path: "/api/app/inventory-expiry/batches",
    body: {
      itemId: item.id,
      batchNo: nearNo,
      quantity: 1,
      expiresAt: utcDay(10),
    },
  });
  assert.equal(duplicate.status, 409);

  const badDate = await ctx.request({
    method: "POST",
    path: "/api/app/inventory-expiry/batches",
    body: {
      itemId: item.id,
      batchNo: `BAD-${suffix}`,
      quantity: 1,
      expiresAt: "2026-13-40",
    },
  });
  assert.equal(badDate.status, 400);

  const missingItem = await ctx.request({
    method: "POST",
    path: "/api/app/inventory-expiry/batches",
    body: {
      itemId: `inv_missing_${suffix}`,
      batchNo: `ORPHAN-${suffix}`,
      quantity: 1,
      expiresAt: utcDay(5),
    },
  });
  assert.equal(missingItem.status, 404);

  const deleted = await ctx.request({
    method: "DELETE",
    path: `/api/app/inventory-expiry/batches/${freshBatch.id}`,
  });
  assert.equal(deleted.status, 200);
  assert.equal((deleted.body as { removed: boolean }).removed, true);

  const afterDelete = await ctx.request({
    method: "GET",
    path: `/api/app/inventory-expiry/items/${item.id}/batches`,
  });
  assert.equal(afterDelete.status, 200);
  assert.deepEqual(
    (afterDelete.body as BatchListPayload).batches.map(
      (batch) => batch.batchNo,
    ),
    [expiredNo, nearNo],
  );

  // inventory-core keeps working with expiry data attached to the item.
  const stocked = await ctx.request({
    method: "POST",
    path: `/api/app/inventory-core/items/${item.id}/stock`,
    body: { delta: -4 },
  });
  assert.equal(stocked.status, 200);
  assert.equal((stocked.body as ItemPayload).item.quantity, 16);
}
"}}]}

