```ts
type ExpiryListener = () => void;
const expiryListeners = new Set<ExpiryListener>();

function notifyExpiryChanged(): void {
  for (const listener of Array.from(expiryListeners)) listener();
}

function useExpiryRevision(): number {
  const [revision, setRevision] = useState(0);
  useEffect(() => {
    const listener: ExpiryListener = () => setRevision((value) => value + 1);
    expiryListeners.add(listener);
    return () => {
      expiryListeners.delete(listener);
    };
  }, []);
  return revision;
}
```

