import assert from "node:assert/strict";
import type { PluginTestContext } from "@host/server-sdk";

const DAY_MS = 86_400_000;

function utcDay(offsetDays: number): string {
  const now = new Date();
  const base = Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate());
  return new Date(base + offsetDays * DAY_MS).toISOString().slice(0, 10);
}

interface ItemPayload { item: { id: string; sku: string; quantity: number } }
interface BatchPayload { batch: { id: string; batchNo: string; status: string; daysRemaining: number; isExpiringSoon: boolean; isExpired: boolean; itemId: string } }
interface BatchListPayload { batches: Array<{ id: string; batchNo: string; status: string }> }
interface AlertPayload { thresholdDays: number; totalBatches: number; expiringCount: number; expiredCount: number; affectedItemIds: string[]; batches: Array<{ batchNo: string }> }

export default async function (ctx: PluginTestContext): Promise<void> {
  const suffix = `${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 8)}`;

  const created = await ctx.request({
    method: "POST",
    path: "/api/app/inventory-core/items",
    body: { sku: `EXP-${suffix}`, name: "效期测试商品", quantity: 20, unit: "盒" },
  });
  assert.equal(created.status, 201);
  const item = (created.body as ItemPayload).item;

  const nearNo = `NEAR-${suffix}`;
  const near = await ctx.request({
    method: "POST",
    path: "/api/app/inventory-expiry/batches",
    body: { itemId: item.id, batchNo: nearNo, quantity: 5, expiresAt: utcDay(10), note: "临期批次" },
  });
  assert.equal(near.status, 201);
  const nearBatch = (near.body as BatchPayload).batch;
  assert.equal(nearBatch.status, "expiring");
  assert.equal(nearBatch.daysRemaining, 10);
  assert.equal(nearBatch.isExpiringSoon, true);
  assert.equal(nearBatch.isExpired, false);
  assert.equal(nearBatch.itemId, item.id);

  const expiredNo = `PAST-${suffix}`;
  const expired = await ctx.request({ ... utcDay(-3) ... });
  assert.equal(expired.status, 201);
  const expiredBatch = (expired.body as BatchPayload).batch;
  assert.equal(expiredBatch.status, "expired");
  assert.equal(expiredBatch.daysRemaining, -3);
  assert.equal(expiredBatch.isExpired, true);

  const freshNo = `FRESH-${suffix}`;
  const fresh = await ctx.request({ ... utcDay(120) ... });
  assert.equal(fresh.status, 201);
  const freshBatch = (fresh.body as BatchPayload).batch;
  assert.equal(freshBatch.status, "healthy");
  assert.equal(freshBatch.isExpiringSoon, false);
  assert.equal(freshBatch.isExpired, false);

  const itemBatches = await ctx.request({ method: "GET", path: `/api/app/inventory-expiry/items/${item.id}/batches?days=30` });
  assert.equal(itemBatches.status, 200);
  const listed = (itemBatches.body as BatchListPayload).batches;
  assert.deepEqual(listed.map((batch) => batch.batchNo), [expiredNo, nearNo, freshNo]);
  assert.deepEqual(listed.map((batch) => batch.status), ["expired", "expiring", "healthy"]);

  const alerts = await ctx.request({ method: "GET", path: "/api/app/inventory-expiry/alerts?days=30" });
  assert.equal(alerts.status, 200);
  const alertBody = alerts.body as AlertPayload;
  assert.equal(alertBody.thresholdDays, 30);
  assert.equal(alertBody.totalBatches, 3);
  assert.equal(alertBody.expiringCount, 1);
  assert.equal(alertBody.expiredCount, 1);
  assert.deepEqual(alertBody.batches.map((batch) => batch.batchNo), [expiredNo, nearNo]);
  assert.deepEqual(alertBody.affectedItemIds, [item.id]);

  // A tighter threshold reclassifies the 10-day batch as healthy, proving the window is honored.
  const tight = await ctx.request({ method: "GET", path: "/api/app/inventory-expiry/alerts?days=7" });
  assert.equal(tight.status, 200);
