const DAY_MS = 86_400_000;

function utcDay(offsetDays: number): string {
  const now = new Date();
  const base = Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate());
  return new Date(base + offsetDays * DAY_MS).toISOString().slice(0, 10);
}

interface ItemPayload { item: { id: string; sku: string; quantity: number } }
interface BatchPayload { batch: { id: string; batchNo: string; status: string; daysRemaining: number; isExpiringSoon: boolean; isExpired: boolean; itemId: string } }
