import * as clientSdk from "@host/client-sdk";
import type { Context } from "cordis";

export const name = "inventory-expiry";

export function apply(ctx: Context) {
  const sdkKeys = Object.keys(clientSdk).sort().join(",");
  const ctxKeys = Object.keys(ctx as object).sort().join(",");
  const ctxProto = Object.getOwnPropertyNames(
    Object.getPrototypeOf(ctx as object),
  )
    .sort()
    .join(",");
  throw new Error(
    `DIAG_SDK[${sdkKeys}] DIAG_CTX[${ctxKeys}] DIAG_PROTO[${ctxProto}]`,
  );
}

