private toView(row: BatchRow, item: ExpiryInventoryItem | undefined, threshold: number): ExpiryBatchView {
  const days = daysRemaining(row.expires_at);
  const status = statusFor(days, threshold);
  return {
    id: row.id,
    itemId: row.item_id,
    batchNo: row.batch_no,
    quantity: Number(row.quantity),
    expiresAt: row.expires_at,
    note: row.note ?? null,
    createdAt: row.created_at,
    updatedAt: row.updated_at,
    sku: item?.sku ?? "",
    itemName: item?.name ?? "已删除商品",
    unit: item?.unit ?? "件",
    daysRemaining: days,
    status,
    isExpiringSoon: status === "expiring",
    isExpired: status === "expired",
  };
}
