type SlotRegistrar = (name: string, component: unknown) => void;
function registerClientSlot(ctx: Context, name: string, component: unknown): void {
  const candidate = ctx as unknown as {
    slot?: SlotRegistrar & { register?: SlotRegistrar };
    slots?: { register?: SlotRegistrar };
    router?: { registerSlot?: SlotRegistrar; slot?: { register?: SlotRegistrar } };
  };
  const registrars: SlotRegistrar[] = [];
  if (typeof candidate.slot === "function") registrars.push(candidate.slot);
  if (candidate.slot && typeof candidate.slot.register === "function") registrars.push(candidate.slot.register);
  if (candidate.slots && typeof candidate.slots.register === "function") registrars.push(candidate.slots.register);
  if (candidate.router && typeof candidate.router.registerSlot === "function") registrars.push(candidate.router.registerSlot);
  if (candidate.router && candidate.router.slot && typeof candidate.router.slot.register === "function") registrars.push(candidate.router.slot.register);
  if (registrars.length === 0) throw new Error(`No slot registry available to register "${name}"`);
  registrars[0](name, component);
}
```

