sourceFiles.client.tsx:
import type { Context } from "cordis";

export const name = "inventory-expiry";

export function apply(ctx: Context) {
  const candidates = [
    "slot",
    "slots",
    "slotRegistry",
    "registerSlot",
    "registerSlots",
    "registerClientSlot",
    "contribute",
    "client",
    "ui",
    "view",
    "router",
    "routes",
  ];
  const found: string[] = [];
  for (const key of candidates) {
    try {
      const value = (ctx as unknown as Record<string, unknown>)[key];
      let detail = typeof value;
      if (
        value &&
        (typeof value === "object" || typeof value === "function")
      ) {
        const obj = value as object;
        const own = Object.keys(obj).slice(0, 10).join("|");
        const proto = Object.getOwnPropertyNames(Object.getPrototypeOf(obj))
          .slice(0, 20)
          .join("|");
        detail = `${detail}{k:${own};p:${proto}}`;
      }
      found.push(`${key}=${detail}`);
    } catch {
      found.push(`${key}=ERR`);
    }
  }
  throw new Error(`DIAG2[${found.join(" ;; ")}]`);
}

