import { useCallback, useEffect, useState, type FormEvent } from "react";
import type { Context } from "cordis";
import {
  Slot,
  dispatchClientBail,
  useClientContext,
  useClientRoutes,
  useNavigate,
} from "@host/client-sdk";
import type { InventoryItem } from "./contract.d.ts";

async function requestJson<T>(url: string, init?: RequestInit): Promise<T> {
  const response = await fetch(url, {
    ...init,
    headers: {
      "content-type": "application/json",
      ...(init?.headers ?? {}),
    },
  });
  const text = await response.text();
  const data = text ? (JSON.parse(text) as Record<string, unknown>) : {};
  if (!response.ok) {
    const message =
      typeof data.error === "string" && data.error.length > 0
        ? data.error
        : `请求失败 (${response.status})`;
    throw new Error(message);
  }
  return data as T;
}

function InventoryWorkspacePage() {
  const clientCtx = useClientContext();
  const routes = useClientRoutes();
  const navigate = useNavigate();

  const [items, setItems] = useState<InventoryItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [sku, setSku] = useState("");
  const [name, setName] = useState("");
  const [quantity, setQuantity] = useState("10");
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState("");

  const refresh = useCallback(async () => {
    try {
      const data = await requestJson<{ items: InventoryItem[] }>(
        "/api/app/inventory-core/items",
      );
      setItems(data.items ?? []);
      setError("");
    } catch (err) {
      setError(err instanceof Error ? err.message : String(err));
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    void refresh();
  }, [refresh]);

  const handleCreate = async (event: FormEvent) => {
    event.preventDefault();
    if (!sku.trim() || !name.trim() || busy) return;
    setBusy(true);
    setError("");
    try {
      await requestJson<{ item: InventoryItem }>(
        "/api/app/inventory-core/items",
        {
          method: "POST",
          body: JSON.stringify({
            sku: sku.trim(),
            name: name.trim(),
            quantity: Number(quantity) || 0,
          }),
        },
      );
      setSku("");
      setName("");
      setQuantity("10");
      await refresh();
    } catch (err) {
      setError(err instanceof Error ? err.message : String(err));
    } finally {
      setBusy(false);
    }
  };

  const handleAdjust = async (item: InventoryItem, delta: number) => {
    if (busy) return;
    setBusy(true);
    setError("");
    try {
      const nextQuantity = item.quantity + delta;
      const verdict = await dispatchClientBail(
        clientCtx,
        "inventory:before-stock-change",
        { item, delta, nextQuantity },
      );
      if (verdict === false) {
        setError("库存变动已被扩展规则阻止");
        return;
      }
      if (typeof verdict === "string" && verdict.length > 0) {
