function useItemBatches(itemId: string, thresholdDays = 30) {
  const revision = useExpiryRevision();
  const [batches, setBatches] = useState<ExpiryBatchView[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const reload = useCallback(async () => {
    try {
      const data = await requestJson<{ batches: ExpiryBatchView[] }>(`${API}/items/${encodeURIComponent(itemId)}/batches?days=${thresholdDays}`);
      setBatches(data.batches ?? []);
      setError("");
    } catch (err) { setError(...) } finally { setLoading(false); }
  }, [itemId, thresholdDays]);
  useEffect(() => { void reload(); }, [reload, revision]);
  return { batches, loading, error, reload };
}
