", "sourceFiles": {"server.ts": "import { Service, type Context } from "cordis";
import type { ScopedDb } from "@host/server-sdk";
import type {
  CreateExpiryBatchInput,
  ExpiryAlerts,
  ExpiryBatchStatus,
  ExpiryBatchView,
  ExpiryInventoryItem,
  InventoryExpiryService,
} from "./contract.d.ts";

const DEFAULT_THRESHOLD_DAYS = 30;
const MAX_THRESHOLD_DAYS = 3650;
const DAY_MS = 86_400_000;

interface ExpiryBatchRow {
  readonly id: string;
  readonly item_id: string;
  readonly batch_no: string;
  readonly quantity: number;
  readonly expires_at: string;
  readonly note: string | null;
  readonly created_at: string;
  readonly updated_at: string;
}

interface StockChangePayload {
  readonly item: ExpiryInventoryItem;
  readonly delta: number;
  readonly nextQuantity: number;
  readonly reason?: string;
}

interface InventoryReader {
  list(): ExpiryInventoryItem[];
  get(id: string): ExpiryInventoryItem | null;
}

function httpError(
  status: number,
  message: string,
): Error & { status: number } {
  const error = new Error(message) as Error & { status: number };
  error.status = status;
  return error;
}

function parseDateOnly(value: unknown): string | null {
  if (typeof value !== "string" || !/^\d{4}-\d{2}-\d{2}$/.test(value)) {
    return null;
  }
  const timestamp = Date.parse(`${value}T00:00:00.000Z`);
  if (!Number.isFinite(timestamp)) return null;
  const normalized = new Date(timestamp).toISOString().slice(0, 10);
  return normalized === value ? value : null;
}

function daysUntil(expiresAt: string, now: Date = new Date()): number {
  const expiry = Date.parse(`${expiresAt}T00:00:00.000Z`);
  const today = Date.UTC(
    now.getUTCFullYear(),
    now.getUTCMonth(),
    now.getUTCDate(),
  );
  return Math.round((expiry - today) / DAY_MS);
}

function statusFor(
  daysRemaining: number,
  thresholdDays: number,
): ExpiryBatchStatus {
  if (daysRemaining < 0) return "expired";
  if (daysRemaining <= thresholdDays) return "expiring";
  return "healthy";
}

function normalizeThreshold(value?: number): number {
  if (typeof value !== "number" || !Number.isFinite(value)) {
    return DEFAULT_THRESHOLD_DAYS;
  }
  return Math.min(MAX_THRESHOLD_DAYS, Math.max(0, Math.trunc(value)));
}

function readQuery(req: unknown, key: string): string | undefined {
  const query = (req as { query?: Record<string, unknown> }).query;
  const value = query?.[key];
  if (typeof value === "string") return value;
  if (Array.isArray(value) && typeof value[0] === "string") return value[0];
  return undefined;
}

function readNumberQuery(req: unknown, key: string): number | undefined {
  const value = readQuery(req, key);
  if (value === undefined || value.trim() === "") return undefined;
  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed : undefined;
}

function errorResponse(error: unknown): {
  status: number;
  body: { error: string };
} {
  const status =
    typeof (error as { status?: unknown })?.status === "number"
      ? (error as { status: number }).status
      : 400;
  const message = error instanceof Error ? error.message : String(error);
  return { status, body: { error: message } };
}

export default class InventoryExpiryExtension
  extends Service
  implements InventoryExpiryService
{
  private readonly db: ScopedDb;

  constructor(ctx: Context) {
    super(ctx, "inventoryExpiry");
    this.db = ctx.db;

    this.db.exec(`
      CREATE TABLE IF NOT EXISTS plg_inventory_expiry__batches (
        id TEXT PRIMARY KEY,
        item_id TEXT NOT NULL,
        batch_no TEXT NOT NULL,
        quantity INTEGER NOT NULL DEFAULT 0,
        expires_at TEXT NOT NULL,
        note TEXT,
        created_at TEXT NOT NULL,
        updated_at TEXT NOT NULL,
        UNIQUE (item_id, batch_no)
      )
    `);

    (
      ctx as unknown as {
        on(
          event: string,
          listener: (payload: StockChangePayload) => void,
        ): () => void;
      }
    ).on("inventory:before-stock-change", (payload) => {
      this.observeStockChange(payload);
    });

    ctx.http.route("GET", "/batches", (req) => {
      const thresholdDays = normalizeThreshold(readNumberQuery(req, "days"));
      const itemId = readQuery(req, "itemId");
      return { thresholdDays, batches: this.listBatches(itemId, thresholdDays) };
    });

    ctx.http.route("POST", "/batches", async (req) => {
      const body = (req.body ?? {}) as Record<string, unknown>;
      try {
        const batch = await this.registerBatch({
          itemId: typeof body.itemId === "string" ? body.itemId : "",
          batchNo: typeof body.batchNo === "string" ? body.batchNo : "",
          quantity:
            typeof body.quantity === "number" ? body.quantity : Number.NaN,
          expiresAt: typeof body.expiresAt === "string" ? body.expiresAt : "",
          note: typeof body.note === "string" ? body.note : undefined,
        });
        return { status: 201, body: { batch } };
      } catch (error) {
        return errorResponse(error);
      }
    });

    ctx.http.route("GET", "/items/:itemId/batches", (req) => {
      const item = this.inventoryService().get(req.params.itemId);
      if (!item) {
        return { status: 404, body: { error: "Inventory item not found" } };
      }
      const thresholdDays = normalizeThreshold(readNumberQuery(req, "days"));
      return {
        item,
        thresholdDays,
        batches: this.listBatches(item.id, thresholdDays),
      };
    });

    ctx.http.route("GET", "/alerts", (req) => {
      return this.listAlerts(normalizeThreshold(readNumberQuery(req, "days")));
    });

    ctx.http.route("GET", "/batches/:id", (req) => {
      const thresholdDays = normalizeThreshold(readNumberQuery(req, "days"));
      const batch = this.getBatch(req.params.id, thresholdDays);
      if (!batch) {
        return { status: 404, body: { error: "Expiry batch not found" } };
      }
      return { batch };
    });

    ctx.http.route("DELETE", "/batches/:id", (req) => {
      if (!this.removeBatch(req.params.id)) {
        return { status: 404, body: { error: "Expiry batch not found" } };
      }
      return { removed: true };
    });
  }

  listBatches(itemId?: string, thresholdDays?: number): ExpiryBatchView[] {
    const threshold = normalizeThreshold(thresholdDays);
    const rows =
      typeof itemId === "string" && itemId.length > 0
        ? this.db
            .prepare(
              `SELECT id, item_id, batch_no, quantity, expires_at, note, created_at, updated_at
               FROM plg_inventory_expiry__batches
               WHERE item_id = ?
               ORDER BY expires_at ASC, created_at ASC`,
            )
            .all<ExpiryBatchRow>(itemId)
        : this.db
            .prepare(
              `SELECT id, item_id, batch_no, quantity, expires_at, note, created_at, updated_at
               FROM plg_inventory_expiry__batches
               ORDER BY expires_at ASC, created_at ASC`,
            )
            .all<ExpiryBatchRow>();
    const items = this.inventoryIndex();
    return rows.map((row) =>
      this.toView(row, items.get(row.item_id), threshold),
    );
  }

  getBatch(id: string, thresholdDays?: number): ExpiryBatchView | null {
    const row = this.db
      .prepare(
        `SELECT id, item_id, batch_no, quantity, expires_at, note, created_at, updated_at
         FROM plg_inventory_expiry__batches
         WHERE id = ?`,
      )
      .get<ExpiryBatchRow>(id);
    if (!row) return null;
    const item = this.inventoryService().get(row.item_id) ?? undefined;
    return this.toView(row, item, normalizeThreshold(thresholdDays));
  }

  async registerBatch(input: CreateExpiryBatchInput): Promise<ExpiryBatchView> {
    const itemId = typeof input.itemId === "string" ? input.itemId.trim() : "";
    if (!itemId) throw httpError(400, "itemId is required");
    const item = this.inventoryService().get(itemId);
    if (!item) throw httpError(404, `Inventory item not found: ${itemId}`);

    const batchNo =
      typeof input.batchNo === "string" ? input.batchNo.trim() : "";
    if (!batchNo) throw httpError(400, "Batch number is required");

    const expiresAt = parseDateOnly(input.expiresAt);
    if (!expiresAt) {
      throw httpError(400, "expiresAt must be a valid YYYY-MM-DD date");
    }

    if (typeof input.quantity !== "number" || !Number.isFinite(input.quantity)) {
      throw httpError(400, "Batch quantity must be a finite number");
    }
    const quantity = Math.trunc(input.quantity);
    if (quantity < 0) throw httpError(400, "Batch quantity must be >= 0");

    const duplicate = this.db
      .prepare(
        `SELECT id FROM plg_inventory_expiry__batches
         WHERE item_id = ? AND batch_no = ?`,
      )
      .get<{ id: string }>(itemId, batchNo);
    if (duplicate) {
      throw httpError(
        409,
        `Batch ${batchNo} is already registered for this item`,
      );
    }

    const note =
      typeof input.note === "string" && input.note.trim().length > 0
        ? input.note.trim()
        : null;
    const id = `exp_${Date.now().toString(36)}_${Math.random()
      .toString(36)
      .slice(2, 8)}`;
    const now = new Date().toISOString();

    this.db
      .prepare(
        `INSERT INTO plg_inventory_expiry__batches
           (id, item_id, batch_no, quantity, expires_at, note, created_at, updated_at)
         VALUES (?, ?, ?, ?, ?, ?, ?, ?)`,
      )
      .run(id, itemId, batchNo, quantity, expiresAt, note, now, now);

    const batch = this.getBatch(id, DEFAULT_THRESHOLD_DAYS);
    if (!batch) throw httpError(500, "Failed to load the registered batch");

    this.ctx.emit("inventory-expiry:batch-registered", { batch, item });
    if (batch.status !== "healthy") {
      this.ctx.emit("inventory-expiry:alert-raised", {
        itemId,
        sku: item.sku,
        thresholdDays: DEFAULT_THRESHOLD_DAYS,
        batches: [batch],
      });
    }
    return batch;
  }

  removeBatch(id: string): boolean {
    const existing = this.db
      .prepare(`SELECT id FROM plg_inventory_expiry__batches WHERE id = ?`)
      .get<{ id: string }>(id);
    if (!existing) return false;
    this.db
      .prepare(`DELETE FROM plg_inventory_expiry__batches WHERE id = ?`)
      .run(id);
    return true;
  }

  listAlerts(thresholdDays?: number): ExpiryAlerts {
    const threshold = normalizeThreshold(thresholdDays);
    const all = this.listBatches(undefined, threshold);
    const batches = all.filter((batch) => batch.status !== "healthy");
    return {
      thresholdDays: threshold,
      totalBatches: all.length,
      expiringCount: all.filter((batch) => batch.status === "expiring").length,
      expiredCount: all.filter((batch) => batch.status === "expired").length,
      affectedItemIds: Array.from(new Set(batches.map((batch) => batch.itemId))),
      batches,
    };
  }

  private inventoryService(): InventoryReader {
    const service = (this.ctx as unknown as { inventory?: InventoryReader })
      .inventory;
    if (!service) {
      throw httpError(503, "inventory-core service is unavailable");
    }
    return service;
  }

  private inventoryIndex(): Map<string, ExpiryInventoryItem> {
    const index = new Map<string, ExpiryInventoryItem>();
    for (const item of this.inventoryService().list()) {
      index.set(item.id, item);
    }
    return index;
  }

  private toView(
    row: ExpiryBatchRow,
    item: ExpiryInventoryItem | undefined,
    thresholdDays: number,
  ): ExpiryBatchView {
    const daysRemaining = daysUntil(row.expires_at);
    const status = statusFor(daysRemaining, thresholdDays);
    return {
      id: row.id,
      itemId: row.item_id,
      batchNo: row.batch_no,
      quantity: Number(row.quantity),
      expiresAt: row.expires_at,
      note: row.note ?? null,
      createdAt: row.created_at,
      updatedAt: row.updated_at,
      sku: item?.sku ?? "",
      itemName: item?.name ?? "Unknown item",
      unit: item?.unit ?? "件",
      daysRemaining,
      status,
      isExpiringSoon: status === "expiring",
      isExpired: status === "expired",
    };
  }

  private observeStockChange(payload: StockChangePayload): void {
    try {
      if (
        !payload ||
        !payload.item ||
        typeof payload.delta !== "number" ||
        payload.delta >= 0
      ) {
        return;
      }
      const related = this.listAlerts(DEFAULT_THRESHOLD_DAYS).batches.filter(
        (batch) => batch.itemId === payload.item.id,
      );
      if (related.length === 0) return;
      this.ctx.emit("inventory-expiry:alert-raised", {
        itemId: payload.item.id,
        sku: payload.item.sku,
        thresholdDays: DEFAULT_THRESHOLD_DAYS,
        batches: related,
      });
    } catch {
      // Expiry observation must never interfere with inventory-core stock changes.
    }
  }
}
