    method: "POST",
    path: `/api/app/inventory-core/items/${id}/stock`,
    body: { delta: -4 },
  });
  assert.equal(stocked.status, 200);
  assert.equal((stocked.body as { item: { quantity: number } }).item.quantity, 6);
}

