private observeStockChange(payload: StockChangePayload) {
  if (payload.delta >= 0) return;
  const alerts = this.listAlerts(30).batches.filter(b => b.itemId === payload.item.id && b.status !== "healthy");
  if (alerts.length > 0) {
    this.ctx.emit("inventory-expiry:alert-raised", { itemId: payload.item.id, sku: payload.item.sku, batches: alerts, thresholdDays: 30 });
  }
}
```
