listAlerts implementation:

```ts
listAlerts(thresholdDays = 30): ExpiryAlerts {
  const threshold = normalizeThreshold(thresholdDays);
  const all = this.listBatches();
  const batches = all.filter(b => b.status !== "healthy");
  const expiringCount = all.filter(b => b.status === "expiring").length;
  const expiredCount = all.filter(b => b.status === "expired").length;
  const itemIds = Array.from(new Set(batches.map(b => b.itemId)));
  return { thresholdDays: threshold, totalBatches: all.length, expiringCount, expiredCount, itemIds, batches };
}
```
