import { Service, type Context } from "cordis";
import type { ScopedDb } from "@host/server-sdk";
import type {
  CreateExpiryBatchInput,
  ExpiryAlerts,
  ExpiryBatchStatus,
  ExpiryBatchView,
  ExpiryInventoryItem,
  InventoryExpiryService,
} from "./contract.d.ts";

const DEFAULT_THRESHOLD_DAYS = 30;
const MAX_THRESHOLD_DAYS = 3650;
const DAY_MS = 86_400_000;

interface ExpiryBatchRow {
  readonly id: string;
  readonly item_id: string;
  readonly batch_no: string;
  readonly quantity: number;
  readonly expires_at: string;
  readonly note: string | null;
  readonly created_at: string;
  readonly updated_at: string;
}

interface StockChangePayload {
  readonly item: ExpiryInventoryItem;
  readonly delta: number;
  readonly nextQuantity: number;
  readonly reason?: string;
}

interface InventoryReader {
  list(): ExpiryInventoryItem[];
  get(id: string): ExpiryInventoryItem | null;
}

function httpError(status: number, message: string): Error & { status: number } {
  const error = new Error(message) as Error & { status: number };
  error.status = status;
  return error;
}

function parseDateOnly(value: unknown): string | null {
  if (typeof value !== "string" || !/^\d{4}-\d{2}-\d{2}$/.test(value)) return null;
  const timestamp = Date.parse(`${value}T00:00:00.000Z`);
  if (!Number.isFinite(timestamp)) return null;
  return new Date(timestamp).toISOString().slice(0, 10) === value ? value : null;
}

function daysUntil(expiresAt: string, now: Date = new Date()): number {
  const expiry = Date.parse(`${expiresAt}T00:00:00.000Z`);
  const today = Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate());
  return Math.round((expiry - today) / DAY_MS);
}

function statusFor(daysRemaining: number, thresholdDays: number): ExpiryBatchStatus {
  if (daysRemaining < 0) return "expired";
  if (daysRemaining <= thresholdDays) return "expiring";
  return "healthy";
}

function normalizeThreshold(value?: number): number {
  if (typeof value !== "number" || !Number.isFinite(value)) return DEFAULT_THRESHOLD_DAYS;
  return Math.min(MAX_THRESHOLD_DAYS, Math.max(0, Math.trunc(value)));
}

function readQuery(req: unknown, key: string): string | undefined {
  const query = (req as { query?: Record<string, unknown> }).query;
  const value = query?.[key];
  if (typeof value === "string") return value;
  if (Array.isArray(value) && typeof value[0] === "string") return value[0];
  return undefined;
}

function readNumberQuery(req: unknown, key: string): number | undefined {
  const value = readQuery(req, key);
  if (value === undefined || value.trim() === "") return undefined;
  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed : undefined;
}

function errorResponse(error: unknown): { status: number; body: { error: string } } {
  const status = typeof (error as { status?: unknown })?.status === "number"
    ? (error as { status: number }).status
    : 400;
  const message = error instanceof Error ? error.message : String(error);
  return { status, body: { error: message } };
}
