{"upserts": [{"pluginId": "inventory-expiry", "name": "Inventory Expiry", "dependencies": ["inventory-core"], "sourceFiles": {"client.tsx": "import { useEffect, useState, type FormEvent } from "react";
import type { Context } from "cordis";
import { useNavigate } from "@host/client-sdk";
import type {
  ExpiryAlerts,
  ExpiryBatchStatus,
  ExpiryBatchView,
} from "./contract.d.ts";

const EXPIRY_API = "/api/app/inventory-expiry";
const INVENTORY_API = "/api/app/inventory-core";
const DEFAULT_THRESHOLD_DAYS = 30;
const THRESHOLD_OPTIONS = [7, 30, 60, 90];

const inputClass =
  "rounded border border-line bg-canvas px-2.5 py-1.5 text-sm text-ink";
const primaryButtonClass =
  "rounded-md bg-accent px-3 py-1.5 text-sm font-medium text-surface hover:bg-accent/90 disabled:opacity-50";
const ghostButtonClass =
  "rounded border border-line bg-canvas px-2.5 py-1 text-xs font-medium text-ink hover:bg-line/40 disabled:opacity-50";

interface InventoryItemLike {
  readonly id: string;
  readonly sku: string;
  readonly name: string;
  readonly quantity: number;
  readonly unit: string;
  readonly createdAt: string;
  readonly updatedAt: string;
}

interface ItemSlotProps {
  readonly item: InventoryItemLike;
  readonly refresh: () => Promise<void>;
}

interface ExpiryApiError {
  readonly error?: string;
}

async function requestJson<T>(url: string, init?: RequestInit): Promise<T> {
  const response = await fetch(url, {
    ...init,
    headers: {
      "content-type": "application/json",
      ...(init?.headers ?? {}),
    },
  });
  const text = await response.text();
  const data = text ? (JSON.parse(text) as Record<string, unknown>) : {};
  if (!response.ok) {
    const payload = data as ExpiryApiError;
    const message =
      typeof payload.error === "string" && payload.error.length > 0
        ? payload.error
        : `请求失败 (${response.status})`;
    throw new Error(message);
  }
  return data as T;
}

function errorMessage(error: unknown): string {
  return error instanceof Error ? error.message : String(error);
}

type ExpiryListener = () => void;
const expiryListeners = new Set<ExpiryListener>();

function notifyExpiryChanged(): void {
  for (const listener of Array.from(expiryListeners)) {
    listener();
  }
}

function useExpiryRevision(): number {
  const [revision, setRevision] = useState(0);
  useEffect(() => {
    const listener: ExpiryListener = () => setRevision((value) => value + 1);
    expiryListeners.add(listener);
    return () => {
      expiryListeners.delete(listener);
    };
  }, []);
  return revision;
}

function useBatchFeed(path: string) {
  const revision = useExpiryRevision();
  const [batches, setBatches] = useState<ExpiryBatchView[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");

  useEffect(() => {
    let cancelled = false;
    setLoading(true);
    void (async () => {
      try {
        const data = await requestJson<{ batches?: ExpiryBatchView[] }>(path);
        if (cancelled) return;
        setBatches(data.batches ?? []);
        setError("");
      } catch (err) {
        if (!cancelled) setError(errorMessage(err));
      } finally {
        if (!cancelled) setLoading(false);
      }
    })();
    return () => {
      cancelled = true;
    };
  }, [path, revision]);

  return { batches, loading, error };
}

function useItemBatches(
  itemId: string,
  thresholdDays: number = DEFAULT_THRESHOLD_DAYS,
) {
  return useBatchFeed(
    `${EXPIRY_API}/items/${encodeURIComponent(itemId)}/batches?days=${thresholdDays}`,
  );
}

function useAllBatches(thresholdDays: number) {
  return useBatchFeed(`${EXPIRY_API}/batches?days=${thresholdDays}`);
}

function useExpiryAlerts(thresholdDays: number = DEFAULT_THRESHOLD_DAYS) {
  const revision = useExpiryRevision();
  const [alerts, setAlerts] = useState<ExpiryAlerts | null>(null);
  const [error, setError] = useState("");

  useEffect(() => {
    let cancelled = false;
    void (async () => {
      try {
        const data = await requestJson<ExpiryAlerts>(
          `${EXPIRY_API}/alerts?days=${thresholdDays}`,
        );
        if (cancelled) return;
        setAlerts(data);
        setError("");
      } catch (err) {
        if (!cancelled) setError(errorMessage(err));
      }
    })();
    return () => {
      cancelled = true;
    };
  }, [thresholdDays, revision]);

  return { alerts, error };
}

function useInventoryItems(): InventoryItemLike[] {
  const [items, setItems] = useState<InventoryItemLike[]>([]);
  useEffect(() => {
    let cancelled = false;
    void (async () => {
      try {
        const data = await requestJson<{ items?: InventoryItemLike[] }>(
          `${INVENTORY_API}/items`,
        );
        if (!cancelled) setItems(data.items ?? []);
      } catch {
        // Keep the page usable even when the inventory list cannot be loaded.
      }
    })();
    return () => {
      cancelled = true;
    };
  }, []);
  return items;
}

function expiryBadgeClass(status: ExpiryBatchStatus): string {
  if (status === "expired") {
    return "border border-danger/40 bg-danger/10 text-danger";
  }
  if (status === "expiring") {
    return "border border-accent/40 bg-accent/10 text-accent";
  }
  return "border border-line bg-canvas text-muted";
}

function expiryStatusLabel(status: ExpiryBatchStatus): string {
  if (status === "expired") return "已过期";
  if (status === "expiring") return "临期";
  return "正常";
}

function expiryStatusText(batch: ExpiryBatchView): string {
  if (batch.daysRemaining < 0) {
    return `已过期 ${Math.abs(batch.daysRemaining)} 天`;
  }
  if (batch.daysRemaining === 0) return "今日到期";
  return `${batch.daysRemaining} 天后到期`;
}

function ExpiryHeaderActions() {
  const navigate = useNavigate();
  const { alerts } = useExpiryAlerts();
  const total = (alerts?.expiringCount ?? 0) + (alerts?.expiredCount ?? 0);

  return (
    <button
      type="button"
      data-expiry-header-action="true"
      data-expiry-alert-total={total}
      onClick={() => navigate("/expiry")}
      className={ghostButtonClass}
    >
      效期预警{total > 0 ? ` (${total})` : ""}
    </button>
  );
}

function ExpiryListBanner() {
  const navigate = useNavigate();
  const { alerts, error } = useExpiryAlerts();
  const expiring = alerts?.expiringCount ?? 0;
  const expired = alerts?.expiredCount ?? 0;

  if (error || !alerts || expiring + expired === 0) return null;

  const preview = alerts.batches
    .slice(0, 3)
    .map((batch) => `${batch.sku} ${batch.batchNo}`)
    .join("、");
  const toneClass =
    expired > 0
      ? "border-danger/40 bg-danger/10 text-danger"
      : "border-accent/40 bg-accent/10 text-accent";

  return (
    <div
      role="status"
      data-expiry-alert-banner="true"
      data-expiry-alert-expiring={expiring}
      data-expiry-alert-expired={expired}
      className={`mb-3 flex flex-wrap items-center justify-between gap-2 rounded-md border px-3 py-2 text-xs ${toneClass}`}
    >
      <span>
        效期预警：{expired} 个批次已过期，{expiring} 个批次将在{" "}
        {alerts.thresholdDays} 天内到期
        {preview
          ? `（${preview}${alerts.batches.length > 3 ? " 等" : ""}）`
          : ""}
      </span>
      <button
        type="button"
        data-expiry-banner-link="true"
        onClick={() => navigate("/expiry")}
        className="rounded border border-current/40 bg-surface px-2 py-1 font-medium hover:bg-canvas"
      >
        查看预警明细
      </button>
    </div>
  );
}

function ExpiryItemBadges({ item }: ItemSlotProps) {
  const { batches } = useItemBatches(item.id);
  if (batches.length === 0) return null;

  const expired = batches.filter((batch) => batch.status === "expired").length;
  const expiring = batches.filter(
    (batch) => batch.status === "expiring",
  ).length;
  const status: ExpiryBatchStatus =
    expired > 0 ? "expired" : expiring > 0 ? "expiring" : "healthy";
  const label =
    expired > 0
      ? `已过期 ${expired} 批`
      : expiring > 0
        ? `临期 ${expiring} 批`
        : `效期正常 ${batches.length} 批`;

  return (
    <span
      data-expiry-badge={item.sku}
      data-expiry-badge-status={status}
      className={`rounded px-2 py-0.5 text-[11px] font-medium ${expiryBadgeClass(status)}`}
    >
      {label}
    </span>
  );
}

function ExpiryItemDetail({ item }: ItemSlotProps) {
  const { batches, loading, error: loadError } = useItemBatches(item.id);
  const [batchNo, setBatchNo] = useState("");
  const [quantity, setQuantity] = useState("1");
  const [expiresAt, setExpiresAt] = useState("");
  const [busy, setBusy] = useState(false);
  const [formError, setFormError] = useState("");

  const handleSubmit = async (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    if (busy) return;
    if (!batchNo.trim()) {
      setFormError("请填写批次号");
      return;
    }
    if (!expiresAt) {
      setFormError("请选择效期日期");
      return;
    }
    const parsedQuantity = Number(quantity);
    if (!Number.isFinite(parsedQuantity) || parsedQuantity < 0) {
      setFormError("批次数量必须为非负数字");
      return;
    }
    setBusy(true);
    setFormError("");
    try {
      await requestJson(`${EXPIRY_API}/batches`, {
        method: "POST",
        body: JSON.stringify({
          itemId: item.id,
          batchNo: batchNo.trim(),
          quantity: Math.trunc(parsedQuantity),
          expiresAt,
        }),
      });
      setBatchNo("");
      setQuantity("1");
      setExpiresAt("");
      notifyExpiryChanged();
    } catch (err) {
      setFormError(errorMessage(err));
    } finally {
      setBusy(false);
    }
  };

  const handleDelete = async (batch: ExpiryBatchView) => {
    if (busy) return;
    setBusy(true);
    setFormError("");
    try {
      await requestJson(
        `${EXPIRY_API}/batches/${encodeURIComponent(batch.id)}`,
        { method: "DELETE" },
      );
      notifyExpiryChanged();
    } catch (err) {
      setFormError(errorMessage(err));
    } finally {
      setBusy(false);
    }
  };

  const message = formError || loadError;

  return (
    <div
      data-expiry-detail={item.sku}
      className="mt-2 border-t border-line pt-2"
    >
      <div className="flex items-center justify-between gap-2">
        <span className="text-xs font-medium text-muted">效期批次</span>
        <span className="text-[11px] text-muted">
          临期阈值 {DEFAULT_THRESHOLD_DAYS} 天
        </span>
      </div>

      {message && (
        <div
          role="alert"
          data-expiry-detail-error="true"
          className="mt-1 rounded border border-danger/40 bg-danger/10 px-2 py-1 text-xs text-danger"
        >
          {message}
        </div>
      )}

      {loading ? (
        <p className="mt-1 text-xs text-muted">加载效期批次中…</p>
      ) : batches.length === 0 ? (
        <p data-expiry-empty={item.sku} className="mt-1 text-xs text-muted">
          暂无批次效期登记
        </p>
      ) : (
        <ul className="mt-1 space-y-1">
          {batches.map((batch) => (
            <li
              key={batch.id}
              data-expiry-batch-row={batch.batchNo}
              data-expiry-batch-status={batch.status}
              className="flex flex-wrap items-center justify-between gap-2 rounded border border-line/70 bg-canvas/60 px-2 py-1 text-xs"
            >
              <span className="font-mono text-muted">{batch.batchNo}</span>
              <span className="text-muted">
                {batch.quantity} {batch.unit}
              </span>
              <span className="text-muted">{batch.expiresAt}</span>
              <span
                className={
                  batch.status === "expired"
                    ? "font-medium text-danger"
                    : batch.status === "expiring"
                      ? "font-medium text-accent"
                      : "text-muted"
                }
              >
                {expiryStatusText(batch)}
              </span>
              <button
                type="button"
                data-expiry-batch-delete={batch.batchNo}
                disabled={busy}
                onClick={() => void handleDelete(batch)}
                className="rounded border border-line bg-surface px-2 py-0.5 text-[11px] text-muted hover:bg-line/40 disabled:opacity-50"
              >
                删除
              </button>
            </li>
          ))}
        </ul>
      )}

      <form
        onSubmit={(event) => void handleSubmit(event)}
        data-expiry-batch-form={item.sku}
        className="mt-2 flex flex-wrap items-center gap-2"
      >
        <input
          type="text"
          value={batchNo}
          onChange={(event) => setBatchNo(event.target.value)}
          placeholder="批次号"
          data-expiry-batch-input={item.sku}
          className={`${inputClass} w-28 text-xs`}
        />
        <input
          type="number"
          min={0}
          value={quantity}
          onChange={(event) => setQuantity(event.target.value)}
          placeholder="批次数量"
          data-expiry-batch-qty-input={item.sku}
          className={`${inputClass} w-20 text-xs`}
        />
        <input
          type="date"
          value={expiresAt}
          onChange={(event) => setExpiresAt(event.target.value)}
          data-expiry-batch-date-input={item.sku}
          className={`${inputClass} text-xs`}
        />
        <button
          type="submit"
          disabled={busy}
          data-expiry-batch-submit={item.sku}
          className="rounded-md bg-accent px-2.5 py-1 text-xs font-medium text-surface hover:bg-accent/90 disabled:opacity-50"
        >
          登记效期
        </button>
      </form>
    </div>
  );
}

function ExpiryAlertsPage() {
  const [thresholdDays, setThresholdDays] = useState(DEFAULT_THRESHOLD_DAYS);
  const {
    batches,
    loading,
    error: loadError,
  } = useAllBatches(thresholdDays);
  const items = useInventoryItems();

  const [itemId, setItemId] = useState("");
  const [batchNo, setBatchNo] = useState("");
  const [quantity, setQuantity] = useState("1");
  const [expiresAt, setExpiresAt] = useState("");
  const [busy, setBusy] = useState(false);
  const [formError, setFormError] = useState("");

  useEffect(() => {
    if (!itemId && items.length > 0) setItemId(items[0].id);
  }, [itemId, items]);

  const expiringCount = batches.filter(
    (batch) => batch.status === "expiring",
  ).length;
  const expiredCount = batches.filter(
    (batch) => batch.status === "expired",
  ).length;

  const handleRegister = async (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    if (busy || !itemId) return;
    if (!batchNo.trim()) {
      setFormError("请填写批次号");
      return;
    }
    if (!expiresAt) {
      setFormError("请选择效期日期");
      return;
    }
    const parsedQuantity = Number(quantity);
    if (!Number.isFinite(parsedQuantity) || parsedQuantity < 0) {
      setFormError("批次数量必须为非负数字");
      return;
    }
    setBusy(true);
    setFormError("");
    try {
      await requestJson(`${EXPIRY_API}/batches`, {
        method: "POST",
        body: JSON.stringify({
          itemId,
          batchNo: batchNo.trim(),
          quantity: Math.trunc(parsedQuantity),
          expiresAt,
        }),
      });
      setBatchNo("");
      setQuantity("1");
      setExpiresAt("");
      notifyExpiryChanged();
    } catch (err) {
      setFormError(errorMessage(err));
    } finally {
      setBusy(false);
    }
  };

  const handleDelete = async (batch: ExpiryBatchView) => {
    if (busy) return;
    setBusy(true);
    setFormError("");
    try {
      await requestJson(
        `${EXPIRY_API}/batches/${encodeURIComponent(batch.id)}`,
        { method: "DELETE" },
      );
      notifyExpiryChanged();
    } catch (err) {
      setFormError(errorMessage(err));
    } finally {
      setBusy(false);
    }
  };

  const message = formError || loadError;

  return (
    <div data-expiry-page="true" className="mx-auto max-w-5xl p-6 text-ink">
      <header className="mb-4 flex flex-wrap items-end justify-between gap-3 border-b border-line pb-3">
        <div>
          <h1 className="text-lg font-semibold">效期预警</h1>
          <p className="text-xs text-muted">
            按库存批次登记效期，集中查看临期与过期批次
          </p>
        </div>
        <label className="flex items-center gap-2 text-xs text-muted">
          预警阈值
          <select
            value={thresholdDays}
            onChange={(event) => setThresholdDays(Number(event.target.value))}
            data-expiry-threshold-select="true"
            className="rounded border border-line bg-surface px-2 py-1 text-xs text-ink"
          >
            {THRESHOLD_OPTIONS.map((days) => (
              <option key={days} value={days}>
                {days} 天
              </option>
            ))}
          </select>
        </label>
      </header>

      <div
        data-expiry-summary="true"
        className="mb-4 grid gap-2 sm:grid-cols-3"
      >
        <div className="rounded-lg border border-line bg-surface p-3">
          <p className="text-xs text-muted">批次总数</p>
          <p
            data-expiry-total-count={batches.length}
            className="font-mono text-lg font-semibold"
          >
            {batches.length}
          </p>
        </div>
        <div className="rounded-lg border border-line bg-surface p-3">
          <p className="text-xs text-muted">临期批次</p>
          <p
            data-expiry-expiring-count={expiringCount}
            className="font-mono text-lg font-semibold text-accent"
          >
            {expiringCount}
          </p>
        </div>
        <div className="rounded-lg border border-line bg-surface p-3">
          <p className="text-xs text-muted">已过期批次</p>
          <p
            data-expiry-expired-count={expiredCount}
            className="font-mono text-lg font-semibold text-danger"
          >
            {expiredCount}
          </p>
        </div>
      </div>

      {message && (
        <div
          role="alert"
          data-expiry-page-error="true"
          className="mb-3 rounded-md border border-danger/40 bg-danger/10 px-3 py-2 text-xs text-danger"
        >
          {message}
        </div>
      )}

      <form
        onSubmit={(event) => void handleRegister(event)}
        data-expiry-create-form="true"
        className="mb-4 flex flex-wrap items-end gap-2 rounded-lg border border-line bg-surface p-3"
      >
        <label className="flex min-w-44 flex-col gap-1 text-[11px] text-muted">
          库存商品
          <select
            value={itemId}
            onChange={(event) => setItemId(event.target.value)}
            data-expiry-item-select="true"
            className={`${inputClass} min-w-44 text-xs`}
          >
            {items.length === 0 && <option value="">暂无库存商品</option>}
            {items.map((item) => (
              <option key={item.id} value={item.id}>
                {item.sku} · {item.name}
              </option>
            ))}
          </select>
        </label>
        <label className="flex flex-col gap-1 text-[11px] text-muted">
          批次号
          <input
            type="text"
            value={batchNo}
            onChange={(event) => setBatchNo(event.target.value)}
            placeholder="如 BATCH-001"
            data-expiry-page-batch-input="true"
            className={`${inputClass} w-32 text-xs`}
          />
        </label>
        <label className="flex flex-col gap-1 text-[11px] text-muted">
          数量
          <input
            type="number"
            min={0}
            value={quantity}
            onChange={(event) => setQuantity(event.target.value)}
            data-expiry-page-qty-input="true"
            className={`${inputClass} w-20 text-xs`}
          />
        </label>
        <label className="flex flex-col gap-1 text-[11px] text-muted">
          效期
          <input
            type="date"
            value={expiresAt}
            onChange={(event) => setExpiresAt(event.target.value)}
            data-expiry-page-date-input="true"
            className={`${inputClass} text-xs`}
          />
        </label>
        <button
          type="submit"
          disabled={busy || !itemId}
          data-expiry-page-submit="true"
          className={primaryButtonClass}
        >
          登记批次效期
        </button>
        {items.length === 0 && (
          <span className="text-[11px] text-muted">
            请先在库存管理中新增商品
          </span>
        )}
      </form>

      {loading ? (
        <div className="py-8 text-center text-sm text-muted">加载效期批次中…</div>
      ) : batches.length === 0 ? (
        <div
          data-expiry-empty-state="true"
          className="rounded-lg border border-dashed border-line py-8 text-center text-sm text-muted"
        >
          暂无批次效期记录
        </div>
      ) : (
        <ul data-expiry-batch-list="true" className="space-y-2">
          {batches.map((batch) => (
            <li
              key={batch.id}
              data-expiry-page-row={batch.batchNo}
              data-expiry-page-status={batch.status}
              className="rounded-lg border border-line bg-surface p-3"
            >
              <div className="flex flex-wrap items-center justify-between gap-2">
                <div className="flex flex-wrap items-center gap-2">
                  <span className="rounded bg-canvas px-2 py-0.5 font-mono text-xs text-muted">
                    {batch.sku}
                  </span>
                  <span className="text-sm font-medium">{batch.itemName}</span>
                  <span className="font-mono text-xs text-muted">
                    批次 {batch.batchNo}
                  </span>
                  <span
                    className={`rounded px-2 py-0.5 text-[11px] font-medium ${expiryBadgeClass(batch.status)}`}
                  >
                    {expiryStatusLabel(batch.status)}
                  </span>
                </div>
                <div className="flex flex-wrap items-center gap-2 text-xs text-muted">
                  <span>
                    {batch.quantity} {batch.unit}
                  </span>
                  <span>{batch.expiresAt}</span>
                  <span
                    className={
                      batch.status === "expired" ? "font-medium text-danger" : ""
                    }
                  >
                    {expiryStatusText(batch)}
                  </span>
                  <button
                    type="button"
                    data-expiry-page-delete={batch.batchNo}
                    disabled={busy}
                    onClick={() => void handleDelete(batch)}
                    className="rounded border border-line bg-canvas px-2 py-0.5 text-[11px] text-muted hover:bg-line/40 disabled:opacity-50"
                  >
                    删除
                  </button>
                </div>
              </div>
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}

interface SlotRegistry {
  register(name: string, component: unknown, options?: unknown): void;
}

function registerClientSlot(
  ctx: Context,
  name: string,
  component: unknown,
): void {
  const slots = (ctx as unknown as { slots?: SlotRegistry }).slots;
  if (!slots || typeof slots.register !== "function") {
    console.warn(
      `[inventory-expiry] Client slot registry unavailable; unable to mount "${name}".`,
    );
    return;
  }
  slots.register(name, component);
}

export const name = "inventory-expiry";

export function apply(ctx: Context) {
  ctx.router.registerPage({
    path: "/expiry",
    navLabel: "效期预警",
    component: ExpiryAlertsPage,
  });

  registerClientSlot(ctx, "inventory.header.actions", ExpiryHeaderActions);
  registerClientSlot(ctx, "inventory.list.banner", ExpiryListBanner);
  registerClientSlot(ctx, "inventory.item.badges", ExpiryItemBadges);
  registerClientSlot(ctx, "inventory.item.detail", ExpiryItemDetail);
}
