import assert from "node:assert/strict";
import type { PluginTestContext } from "@host/server-sdk";

const DAY_MS = 86_400_000;

function utcDay(offsetDays: number): string {
  const now = new Date();
  const base = Date.UTC(
    now.getUTCFullYear(),
    now.getUTCMonth(),
    now.getUTCDate(),
  );
  return new Date(base + offsetDays * DAY_MS).toISOString().slice(0, 10);
}

interface ItemPayload {
  readonly item: {
    readonly id: string;
    readonly sku: string;
    readonly quantity: number;
  };
}

interface BatchPayload {
  readonly batch: {
    readonly id: string;
    readonly itemId: string;
    readonly batchNo: string;
    readonly status: string;
    readonly daysRemaining: number;
    readonly isExpiringSoon: boolean;
    readonly isExpired: boolean;
  };
}

interface BatchListPayload {
  readonly batches: ReadonlyArray<{
    readonly id: string;
    readonly itemId: string;
    readonly batchNo: string;
    readonly status: string;
  }>;
}

interface AlertPayload {
  readonly thresholdDays: number;
  readonly totalBatches: number;
  readonly expiringCount: number;
  readonly expiredCount: number;
  readonly affectedItemIds: readonly string[];
  readonly batches: ReadonlyArray<{
    readonly itemId: string;
    readonly batchNo: string;
  }>;
}

export default async function (ctx: PluginTestContext): Promise<void> {
  const suffix = `${Date.now().toString(36)}${Math.random()
    .toString(36)
    .slice(2, 8)}`;

  const created = await ctx.request({
    method: "POST",
    path: "/api/app/inventory-core/items",
    body: {
      sku: `EXP-${suffix}`,
      name: "效期测试商品",
      quantity: 20,
      unit: "盒",
    },
  });
  assert.equal(created.status, 201, "step:create-core-item");
  const item = (created.body as ItemPayload).item;

  const nearNo = `NEAR-${suffix}`;
  const near = await ctx.request({
    method: "POST",
    path: "/api/app/inventory-expiry/batches",
    body: {
      itemId: item.id,
      batchNo: nearNo,
      quantity: 5,
      expiresAt: utcDay(10),
      note: "临期批次",
    },
  });
  assert.equal(near.status, 201, "step:register-near-batch");
  const nearBatch = (near.body as BatchPayload).batch;
  assert.equal(nearBatch.itemId, item.id, "step:near-item-id");
  assert.equal(nearBatch.status, "expiring", "step:near-status");
  assert.equal(nearBatch.daysRemaining, 10, "step:near-days");
  assert.equal(nearBatch.isExpiringSoon, true, "step:near-expiring");
  assert.equal(nearBatch.isExpired, false, "step:near-not-expired");

  const expiredNo = `PAST-${suffix}`;
  const expired = await ctx.request({
    method: "POST",
    path: "/api/app/inventory-expiry/batches",
    body: {
      itemId: item.id,
      batchNo: expiredNo,
      quantity: 2,
      expiresAt: utcDay(-3),
    },
  });
  assert.equal(expired.status, 201, "step:register-expired-batch");
  const expiredBatch = (expired.body as BatchPayload).batch;
  assert.equal(expiredBatch.status, "expired", "step:expired-status");
  assert.equal(expiredBatch.daysRemaining, -3, "step:expired-days");
  assert.equal(expiredBatch.isExpired, true, "step:expired-flag");
  assert.equal(expiredBatch.isExpiringSoon, false, "step:expired-not-expiring");

  const freshNo = `FRESH-${suffix}`;
  const fresh = await ctx.request({
    method: "POST",
    path: "/api/app/inventory-expiry/batches",
    body: {
      itemId: item.id,
      batchNo: freshNo,
      quantity: 8,
      expiresAt: utcDay(120),
    },
  });
  assert.equal(fresh.status, 201, "step:register-fresh-batch");
  const freshBatch = (fresh.body as BatchPayload).batch;
  assert.equal(freshBatch.status, "healthy", "step:fresh-status");
  assert.equal(freshBatch.isExpiringSoon, false, "step:fresh-not-expiring");
  assert.equal(freshBatch.isExpired, false, "step:fresh-not-expired");

  const single = await ctx.request({
    method: "GET",
    path: `/api/app/inventory-expiry/batches/${nearBatch.id}`,
  });
  assert.equal(single.status, 200, "step:get-single-batch");
  assert.equal(
    (single.body as BatchPayload).batch.batchNo,
    nearNo,
    "step:single-batch-no",
  );

  const itemBatches = await ctx.request({
    method: "GET",
    path: `/api/app/inventory-expiry/items/${item.id}/batches?days=30`,
  });
  assert.equal(itemBatches.status, 200, "step:get-item-batches");
  const listed = (itemBatches.body as BatchListPayload).batches;
  assert.deepEqual(
    listed.map((batch) => batch.batchNo),
    [expiredNo, nearNo, freshNo],
    "step:item-batch-order",
  );
  assert.deepEqual(
    listed.map((batch) => batch.status),
    ["expired", "expiring", "healthy"],
    "step:item-batch-statuses",
  );

  const alerts = await ctx.request({
    method: "GET",
    path: "/api/app/inventory-expiry/alerts?days=30",
  });
  assert.equal(alerts.status, 200, "step:get-alerts");
  const alertBody = alerts.body as AlertPayload;
  assert.equal(alertBody.thresholdDays, 30, "step:alert-threshold");
  assert.ok(alertBody.totalBatches >= 3, "step:alert-total");
  assert.ok(alertBody.expiringCount >= 1, "step:alert-expiring-count");
  assert.ok(alertBody.expiredCount >= 1, "step:alert-expired-count");
  assert.ok(
    alertBody.affectedItemIds.includes(item.id),
    "step:alert-item-ids",
  );
  assert.deepEqual(
    alertBody.batches
      .filter((batch) => batch.itemId === item.id)
      .map((batch) => batch.batchNo),
    [expiredNo, nearNo],
    "step:alert-scoped-batches",
  );

  const tight = await ctx.request({
    method: "GET",
    path: "/api/app/inventory-expiry/alerts?days=7",
  });
  assert.equal(tight.status, 200, "step:get-tight-alerts");
  const tightBody = tight.body as AlertPayload;
  assert.equal(tightBody.thresholdDays, 7, "step:tight-threshold");
  assert.deepEqual(
    tightBody.batches
      .filter((batch) => batch.itemId === item.id)
      .map((batch) => batch.batchNo),
    [expiredNo],
    "step:tight-scoped-batches",
  );

  const duplicate = await ctx.request({
    method: "POST",
    path: "/api/app/inventory-expiry/batches",
    body: {
      itemId: item.id,
      batchNo: nearNo,
      quantity: 1,
      expiresAt: utcDay(10),
    },
  });
  assert.equal(duplicate.status, 409, "step:duplicate-batch");

  const badDate = await ctx.request({
    method: "POST",
    path: "/api/app/inventory-expiry/batches",
    body: {
      itemId: item.id,
      batchNo: `BAD-${suffix}`,
      quantity: 1,
      expiresAt: "2026-13-40",
    },
  });
  assert.equal(badDate.status, 400, "step:bad-date");

  const missingItem = await ctx.request({
    method: "POST",
    path: "/api/app/inventory-expiry/batches",
    body: {
      itemId: `inv_missing_${suffix}`,
      batchNo: `ORPHAN-${suffix}`,
      quantity: 1,
      expiresAt: utcDay(5),
    },
  });
  assert.equal(missingItem.status, 404, "step:missing-item");

  const deleted = await ctx.request({
    method: "DELETE",
    path: `/api/app/inventory-expiry/batches/${freshBatch.id}`,
  });
  assert.equal(deleted.status, 200, "step:delete-batch");
  assert.equal(
    (deleted.body as { removed: boolean }).removed,
    true,
    "step:delete-removed-flag",
  );

  const afterDelete = await ctx.request({
    method: "GET",
    path: `/api/app/inventory-expiry/items/${item.id}/batches`,
  });
  assert.equal(afterDelete.status, 200, "step:get-item-batches-after-delete");
  assert.deepEqual(
    (afterDelete.body as BatchListPayload).batches.map(
      (batch) => batch.batchNo,
    ),
    [expiredNo, nearNo],
    "step:item-batches-after-delete",
  );

  // inventory-core keeps working with expiry data attached to the item.
  const stocked = await ctx.request({
    method: "POST",
    path: `/api/app/inventory-core/items/${item.id}/stock`,
    body: { delta: -4 },
  });
  assert.equal(stocked.status, 200, "step:core-stock");
  assert.equal(
    (stocked.body as ItemPayload).item.quantity,
    16,
    "step:core-stock-quantity",
  );
}

