type SlotRegistrar = (name: string, component: unknown) => void;

interface SlotRegistryLike {
  register?: (name: string, component: unknown) => void;
  add?: (name: string, component: unknown) => void;
}

/**
 * Register a component into a host slot. The slot registry is an injectable
 * client service; the caller passes a context scoped with `slot` injected.
 */
function registerClientSlot(
  ctx: Context,
  name: string,
  component: unknown,
): void {
  const runtime = ctx as unknown as {
    slot?: SlotRegistryLike | SlotRegistrar;
    slots?: SlotRegistryLike;
    slotRegistry?: SlotRegistryLike;
    registerSlot?: SlotRegistrar;
    client?: { slot?: SlotRegistryLike; slots?: SlotRegistryLike };
    router?: SlotRegistryLike & {
      registerSlot?: SlotRegistrar;
      slot?: SlotRegistryLike;
      slots?: SlotRegistryLike;
    };
  };

  const candidates: SlotRegistrar[] = [];
  const slotRegistry =
    runtime.slot && typeof runtime.slot === "object"
      ? runtime.slot
      : undefined;
  if (slotRegistry && typeof slotRegistry.register === "function") {
    candidates.push(slotRegistry.register.bind(slotRegistry));
  }
  if (runtime.slots && typeof runtime.slots.register === "function") {
    candidates.push(runtime.slots.register.bind(runtime.slots));
  }
  if (
    runtime.slotRegistry &&
    typeof runtime.slotRegistry.register === "function"
  ) {
    candidates.push(runtime.slotRegistry.register.bind(runtime.slotRegistry));
  }
  if (runtime.client?.slot && typeof runtime.client.slot.register === "function") {
    candidates.push(runtime.client.slot.register.bind(runtime.client.slot));
  }
  if (
    runtime.client?.slots &&
    typeof runtime.client.slots.register === "function"
  ) {
    candidates.push(runtime.client.slots.register.bind(runtime.client.slots));
  }
  if (runtime.router?.registerSlot) {
    candidates.push(runtime.router.registerSlot.bind(runtime.router));
  }
  if (runtime.router?.slot && typeof runtime.router.slot.register === "function") {
    candidates.push(runtime.router.slot.register.bind(runtime.router.slot));
  }
  if (
    runtime.router?.slots &&
    typeof runtime.router.slots.register === "function"
  ) {
    candidates.push(runtime.router.slots.register.bind(runtime.router.slots));
  }
  if (runtime.registerSlot) {
    candidates.push(runtime.registerSlot.bind(runtime));
  }
  if (slotRegistry && typeof slotRegistry.add === "function") {
    candidates.push(slotRegistry.add.bind(slotRegistry));
  }
  if (typeof runtime.slot === "function") {
    candidates.push(runtime.slot);
  }

  const register = candidates[0];
  if (!register) {
    console.warn(
      `[inventory-expiry] No client slot registry found; unable to mount "${name}".`,
    );
    return;
  }
  register(name, component);
}

export const name = "inventory-expiry";
export const inject = ["slot"];

export function apply(ctx: Context) {
  ctx.router.registerPage({
    path: "/expiry",
    navLabel: "效期预警",
    component: ExpiryAlertsPage,
  });

  (
    ctx as unknown as {
      inject(
        deps: string[],
        callback: (scoped: Context) => void,
      ): unknown;
    }
  ).inject(["slot"], (slotCtx) => {
    registerClientSlot(slotCtx, "inventory.header.actions", ExpiryHeaderActions);
    registerClientSlot(slotCtx, "inventory.list.banner", ExpiryListBanner);
    registerClientSlot(slotCtx, "inventory.item.badges", ExpiryItemBadges);
    registerClientSlot(slotCtx, "inventory.item.detail", ExpiryItemDetail);
  });
}
"}}]}

