private handleStockChange(payload: StockChangePayload): void {
  if (!payload || !payload.item || payload.delta >= 0) return;
  try {
    const alerts = this.listAlerts(DEFAULT_THRESHOLD_DAYS);
    const related = alerts.batches.filter(b => b.itemId === payload.item.id);
